#' GPU: Scrublet doublet detection
#'
#' @description
#' `r lifecycle::badge("experimental")`
#' GPU equivalent of `bixverse::rs_sc_scrublet`. The PCA of the observed
#' cells, the projection of the simulated doublets and the kNN over the
#' combined embedding run on the WGPU backend. HVG selection, doublet
#' simulation, scoring and the Otsu threshold stay on the CPU. Which nearest
#' neighbour index runs is decided by the `knn_backend` element of
#' `scrublet_params`.
#'
#' @param f_path_gene String. Path to the `counts_genes.bin` file.
#' @param f_path_cell String. Path to the `counts_cells.bin` file.
#' @param cells_to_keep Integer vector. The indices (0-indexed!) of the cells
#' to include in this analysis.
#' @param scrublet_params List. Parameter list, see
#' [params_scrublet_gpu()].
#' @param seed Integer. Seed for reproducibility purposes.
#' @param verbose Integer. `0L` - quiet; `1L` - normal verbosity; `2L` -
#' detailed verbosity.
#' @param streaming Boolean. Shall the data be streamed for the HVG
#' calculations.
#' @param return_combined_pca Boolean. Shall the generated PCA be returned.
#' @param return_pairs Boolean. Shall the parents of the simulated cells be
#' returned.
#'
#' @returns A list with
#' \itemize{
#'   \item predicted_doublets - Boolean vector indicating which observed cells
#'   were predicted as doublets (TRUE = doublet, FALSE = singlet).
#'   \item doublet_scores_obs - Numerical vector with the likelihood of being
#'   a doublet for the observed cells.
#'   \item doublet_scores_sim - Numerical vector with the likelihood of being
#'   a doublet for the simulated cells.
#'   \item doublet_errors_obs - Numerical vector with the standard errors of
#'   the scores for the observed cells.
#'   \item z_scores - Z-scores for the observed cells. Represents:
#'   `score - threshold / error`.
#'   \item threshold - Used threshold.
#'   \item detected_doublet_rate - Fraction of cells that are called as
#'   doublet.
#'   \item detectable_doublet_fraction - Fraction of simulated doublets with
#'   scores above the threshold.
#'   \item overall_doublet_rate - Estimated overall doublet rate.
#'   \item pca - Optional PCA embeddings across the original cells and
#'   simulated doublets.
#'   \item pair_1 - Optional index of the parent cell 1 of the simulated
#'   doublets.
#'   \item pair_2 - Optional index of the parent cell 2 of the simulated
#'   doublets.
#' }
#'
#' @export
#'
#' @references Wolock, et al., Cell Syst, 2020
#'
#' @keywords internal
rs_sc_scrublet_gpu <- function(f_path_gene, f_path_cell, cells_to_keep, scrublet_params, seed, verbose, streaming, return_combined_pca, return_pairs) .Call(wrap__rs_sc_scrublet_gpu, f_path_gene, f_path_cell, cells_to_keep, scrublet_params, seed, verbose, streaming, return_combined_pca, return_pairs)

#' GPU: SEACells meta cell generation
#'
#' @description
#' `r lifecycle::badge("experimental")`
#' GPU equivalent of `bixverse::rs_get_seacells`. Both Frank-Wolfe solves, the
#' B-gradient argmin and the per-cell A columns, are dispatched to the WGPU
#' backend. The kNN graph, the kernel matrix, the RSS evaluation and the
#' aggregation into pseudo-bulk counts all stay on the CPU.
#'
#' @param f_path String. Path to the `counts_cells.bin` file.
#' @param embd Numeric matrix. Cells x components embedding, one row per
#' QC-passing cell.
#' @param cells_to_keep Optional integer vector. 0-indexed original row indices
#' the embedding was built from, in embedding row order.
#' @param cells_to_use Optional integer vector. 0-indexed original row indices
#' to narrow the run to. Forces a kNN rebuild on that subset.
#' @param knn_data Optional list. Precomputed kNN graph with `indices`, `dist`,
#' `dist_metric` and `k`. Ignored when `cells_to_use` is set.
#' @param seacells_params Named list. See [bixverse::params_sc_seacells()].
#' @param target_size Double. Library target size the meta cells are
#' normalised to.
#' @param seed Integer. Random seed.
#' @param verbose Integer. `0L` - quiet; `1L` - normal; `2L` - detailed.
#'
#' @returns A list with the cell assignments, the aggregated meta cell counts
#' in compressed sparse form, the RSS history and the archetype cell indices.
#'
#' @export
#'
#' @references Persad, et al., Nat. Biotechnol., 2023.
#'
#' @keywords internal
rs_seacells_gpu <- function(f_path, embd, cells_to_keep, cells_to_use, knn_data, seacells_params, target_size, seed, verbose) .Call(wrap__rs_seacells_gpu, f_path, embd, cells_to_keep, cells_to_use, knn_data, seacells_params, target_size, seed, verbose)

#' GPU: fast Louvain clustering on the data
#'
#' @description
#' `r lifecycle::badge("experimental")`
#' GPU equivalent of `bixverse::rs_fast_cluster_sc`. Runs k-means clustering on
#' the WGPU backend, followed by a kNN detection on the centroids to then run
#' Louvain clustering on the graph and propagate the membership back to the
#' original data. Everything after the k-means stays on the CPU.
#'
#' @param embd Numeric matrix. The original embedding.
#' @param resolutions Numeric vector. The Louvain resolutions to iterate
#' through.
#' @param n_centroids Optional integer. The number of clusters to find. If
#' not provided, defaults to `sqrt(nrow(embd))`.
#' @param fc_params Named list. See [params_sc_fast_cluster_gpu()].
#' @param snn Boolean. Shall the kNN graph be additionally transformed into
#' an sNN graph.
#' @param return_kmeans Boolean. Shall the k-means centroids and assignments
#' be returned alongside the memberships.
#' @param seed Integer. For reproducibility.
#' @param verbose Integer. `0L` - quiet; `1L` - normal verbosity; `2L` -
#' detailed verbosity.
#'
#' @returns A list with the following elements:
#' \itemize{
#'  \item membership - The memberships across the different resolutions.
#'  \item k_means_cluster - Optional integer vector of k-means assignments.
#'  \item centroids - Optional numeric matrix of k-means centroids.
#' }
#'
#' @export
#'
#' @keywords internal
rs_fast_cluster_gpu <- function(embd, resolutions, n_centroids, fc_params, snn, return_kmeans, seed, verbose) .Call(wrap__rs_fast_cluster_gpu, embd, resolutions, n_centroids, fc_params, snn, return_kmeans, seed, verbose)

#' GPU: fast Louvain clustering on the data (with multiple seeds)
#'
#' @description
#' `r lifecycle::badge("experimental")`
#' GPU equivalent of `bixverse::rs_fast_cluster_sc_grid`. Builds the k-means to
#' kNN/sNN graph once, then runs Louvain with several seeds (derived from the
#' original one) for every resolution. Returns additional metrics around
#' cluster stability and community conductance. Only the k-means runs on the
#' GPU.
#'
#' @param embd Numeric matrix. The original embedding.
#' @param resolutions Numeric vector. The Louvain resolutions to iterate
#' through.
#' @param n_centroids Optional integer. The number of clusters to find. If
#' not provided, defaults to `sqrt(nrow(embd))`.
#' @param fc_params Named list. See [params_sc_fast_cluster_gpu()].
#' @param snn Boolean. Shall the kNN graph be additionally transformed into
#' an sNN graph.
#' @param return_kmeans Boolean. Shall the k-means centroids and assignments
#' be returned alongside the grid results.
#' @param no_seeds Integer. Number of additional seeds to use. Should be >= 2.
#' @param seed Integer. For reproducibility.
#' @param verbose Integer. `0L` - quiet; `1L` - normal verbosity; `2L` -
#' detailed verbosity.
#'
#' @returns A list with the following elements:
#' \itemize{
#'  \item membership - A list with `memberships` (the labels from the seed with
#'  the best conductance, per resolution) and `stats` (the metrics per
#'  resolution).
#'  \item k_means_cluster - Optional integer vector of k-means assignments.
#'  \item centroids - Optional numeric matrix of k-means centroids.
#' }
#'
#' @export
#'
#' @keywords internal
rs_fast_cluster_grid_gpu <- function(embd, resolutions, n_centroids, fc_params, snn, return_kmeans, no_seeds, seed, verbose) .Call(wrap__rs_fast_cluster_grid_gpu, embd, resolutions, n_centroids, fc_params, snn, return_kmeans, no_seeds, seed, verbose)

